455→// UpdateCheckpointSummary updates root-level checkpoint metadata fields that depend
456→// on the full set of sessions already written to the checkpoint.
457→func (s *GitStore) UpdateCheckpointSummary(ctx context.Context, checkpointID id.CheckpointID, combinedAttribution *InitialAttribution) error {
458→	if err := ctx.Err(); err != nil {
459→		return err //nolint:wrapcheck // Propagating context cancellation
460→	}
461→
462→	if err := s.ensureSessionsBranch(); err != nil {
463→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
464→	}
465→
466→	parentHash, rootTreeHash, err := s.getSessionsBranchRef()
467→	if err != nil {
468→		return err
469→	}
470→
471→	basePath := checkpointID.Path() + "/"
472→	checkpointPath := checkpointID.Path()
473→	entries, err := s.flattenCheckpointEntries(rootTreeHash, checkpointPath)
474→	if err != nil {
475→		return err
476→	}
477→
478→	rootMetadataPath := basePath + paths.MetadataFileName
479→	entry, exists := entries[rootMetadataPath]
480→	if !exists {
481→		return ErrCheckpointNotFound
482→	}
483→
484→	summary, err := s.readSummaryFromBlob(entry.Hash)
485→	if err != nil {
486→		return fmt.Errorf("failed to read checkpoint summary: %w", err)
487→	}
488→	summary.CombinedAttribution = combinedAttribution
489→
490→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
491→	if err != nil {
492→		return fmt.Errorf("failed to marshal checkpoint summary: %w", err)
493→	}
494→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
495→	if err != nil {
496→		return fmt.Errorf("failed to create checkpoint summary blob: %w", err)
497→	}
498→	entries[rootMetadataPath] = object.TreeEntry{
499→		Name: rootMetadataPath,
500→		Mode: filemode.Regular,
501→		Hash: metadataHash,
502→	}
503→
504→	newTreeHash, err := s.spliceCheckpointSubtree(rootTreeHash, checkpointID, basePath, entries)
505→	if err != nil {
506→		return err
507→	}
508→
509→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
510→	commitMsg := fmt.Sprintf("Update checkpoint summary for %s", checkpointID)
511→	newCommitHash, err := s.createCommit(newTreeHash, parentHash, commitMsg, authorName, authorEmail)
512→	if err != nil {
513→		return err
514→	}
515→
516→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
517→	newRef := plumbing.NewHashReference(refName, newCommitHash)
518→	if err := s.repo.Storer.SetReference(newRef); err != nil {
519→		return fmt.Errorf("failed to set branch reference: %w", err)
520→	}
521→
522→	return nil
523→}
