602→// aggregateTokenUsage sums two TokenUsage structs.
603→// Returns nil if both inputs are nil.
604→func aggregateTokenUsage(a, b *agent.TokenUsage) *agent.TokenUsage {
605→	if a == nil && b == nil {
606→		return nil
607→	}
608→	result := &agent.TokenUsage{}
609→	if a != nil {
610→		result.InputTokens = a.InputTokens
611→		result.CacheCreationTokens = a.CacheCreationTokens
612→		result.CacheReadTokens = a.CacheReadTokens
613→		result.OutputTokens = a.OutputTokens
614→		result.APICallCount = a.APICallCount
615→	}
616→	if b != nil {
617→		result.InputTokens += b.InputTokens
618→		result.CacheCreationTokens += b.CacheCreationTokens
619→		result.CacheReadTokens += b.CacheReadTokens
620→		result.OutputTokens += b.OutputTokens
621→		result.APICallCount += b.APICallCount
622→	}
623→	return result
624→}
