626→// writeTranscript writes the transcript file from in-memory content or file path.
627→// If the transcript exceeds MaxChunkSize, it's split into multiple chunk files.
628→func (s *GitStore) writeTranscript(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
629→	transcript := opts.Transcript
630→	if len(transcript) == 0 && opts.TranscriptPath != "" {
631→		var readErr error
632→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
633→		if readErr != nil {
634→			// Non-fatal: transcript may not exist yet
635→			transcript = nil
636→		}
637→	}
638→	if len(transcript) == 0 {
639→		return nil
640→	}
641→
642→	// Redact secrets before chunking so content hash reflects redacted content
643→	transcript, err := redact.JSONLBytes(transcript)
644→	if err != nil {
645→		return fmt.Errorf("failed to redact transcript secrets: %w", err)
646→	}
647→
648→	// Chunk the transcript if it's too large
649→	chunks, err := agent.ChunkTranscript(ctx, transcript, opts.Agent)
650→	if err != nil {
651→		return fmt.Errorf("failed to chunk transcript: %w", err)
652→	}
653→
654→	// Write chunk files
655→	for i, chunk := range chunks {
656→		chunkPath := basePath + agent.ChunkFileName(paths.TranscriptFileName, i)
657→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
658→		if err != nil {
659→			return err
660→		}
661→		entries[chunkPath] = object.TreeEntry{
662→			Name: chunkPath,
663→			Mode: filemode.Regular,
664→			Hash: blobHash,
665→		}
666→	}
667→
668→	// Content hash for deduplication (hash of full transcript)
669→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
670→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
671→	if err != nil {
672→		return err
673→	}
674→	entries[basePath+paths.ContentHashFileName] = object.TreeEntry{
675→		Name: basePath + paths.ContentHashFileName,
676→		Mode: filemode.Regular,
677→		Hash: hashBlob,
678→	}
679→	return nil
680→}
