762→// buildCommitMessage constructs the commit message with proper trailers.
763→// The commit subject is always "Checkpoint: <id>" for consistency.
764→// If CommitSubject is provided (e.g., for task checkpoints), it's included in the body.
765→func (s *GitStore) buildCommitMessage(opts WriteCommittedOptions, taskMetadataPath string) string {
766→	var commitMsg strings.Builder
767→
768→	// Subject line is always the checkpoint ID for consistent formatting
769→	fmt.Fprintf(&commitMsg, "Checkpoint: %s\n\n", opts.CheckpointID)
770→
771→	// Include custom description in body if provided (e.g., task checkpoint details)
772→	if opts.CommitSubject != "" {
773→		commitMsg.WriteString(opts.CommitSubject + "\n\n")
774→	}
775→	fmt.Fprintf(&commitMsg, "%s: %s\n", trailers.SessionTrailerKey, opts.SessionID)
776→	fmt.Fprintf(&commitMsg, "%s: %s\n", trailers.StrategyTrailerKey, opts.Strategy)
