954→// ReadLatestSessionContent is a convenience method that reads the latest session's content.
955→// This is equivalent to ReadSessionContent(ctx, checkpointID, len(summary.Sessions)-1).
956→func (s *GitStore) ReadLatestSessionContent(ctx context.Context, checkpointID id.CheckpointID) (*SessionContent, error) {
957→	summary, err := s.ReadCommitted(ctx, checkpointID)
958→	if err != nil {
959→		return nil, err
960→	}
961→	if summary == nil {
962→		return nil, ErrCheckpointNotFound
963→	}
964→	if len(summary.Sessions) == 0 {
