972→// ReadSessionContentByID reads a session's content by its session ID.
973→// This is useful when you have the session ID but don't know its index within the checkpoint.
974→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
975→// Returns an error if no session with the given ID exists in the checkpoint.
976→func (s *GitStore) ReadSessionContentByID(ctx context.Context, checkpointID id.CheckpointID, sessionID string) (*SessionContent, error) {
977→	summary, err := s.ReadCommitted(ctx, checkpointID)
978→	if err != nil {
979→		return nil, err
980→	}
981→	if summary == nil {
982→		return nil, ErrCheckpointNotFound
983→	}
984→
985→	// Iterate through sessions to find the one with matching session ID
986→	for i := range len(summary.Sessions) {
987→		content, readErr := s.ReadSessionContent(ctx, checkpointID, i)
988→		if readErr != nil {
989→			continue
990→		}
991→		if content != nil && content.Metadata.SessionID == sessionID {
992→			return content, nil
993→		}
994→	}
995→
996→	return nil, fmt.Errorf("session %q not found in checkpoint %s", sessionID, checkpointID)
997→}
