1567→// GetGitAuthorFromRepo retrieves the git user.name and user.email,
1568→// checking both the repository-local config and the global ~/.gitconfig.
1569→func GetGitAuthorFromRepo(repo *git.Repository) (name, email string) {
1570→	// Get repository config (includes local settings)
1571→	cfg, err := repo.Config()
1572→	if err == nil {
1573→		name = cfg.User.Name
1574→		email = cfg.User.Email
1575→	}
1576→
1577→	// If not found in local config, try global config
1578→	if name == "" || email == "" {
1579→		globalCfg, err := config.LoadConfig(config.GlobalScope)
1580→		if err == nil {
1581→			if name == "" {
1582→				name = globalCfg.User.Name
1583→			}
1584→			if email == "" {
1585→				email = globalCfg.User.Email
1586→			}
1587→		}
1588→	}
1589→
1590→	// Provide sensible defaults if git user is not configured
1591→	if name == "" {
1592→		name = "Unknown"
1593→	}
1594→	if email == "" {
1595→		email = "unknown@local"
1596→	}
1597→
1598→	return name, email
1599→}
