 20→)
 21→
 22→func newSessionsCmd() *cobra.Command {
 23→	cmd := &cobra.Command{
 24→		Use:   "sessions",
 25→		Short: "Manage agent sessions tracked by Entire",
 26→		Long: `View and manage agent sessions tracked by Entire.
 27→
 28→Commands:
 29→  list    List all sessions across all worktrees
 30→  info    Show detailed information for a specific session
 31→  stop    Stop one or more active sessions
 32→
 33→Examples:
 34→  entire sessions list                     List all sessions
 35→  entire sessions info <session-id>        Show session details
 36→  entire sessions info <session-id> --json Output as JSON
 37→  entire sessions stop                     Interactive stop`,
 38→		PersistentPreRunE: func(cmd *cobra.Command, _ []string) error {
 39→			if _, err := paths.WorktreeRoot(cmd.Context()); err != nil {
 40→				return errors.New("not a git repository")
 41→			}
 42→			return nil
 43→		},
 44→	}
 45→
 46→	cmd.AddCommand(newListCmd())
 47→	cmd.AddCommand(newInfoCmd())
 48→	cmd.AddCommand(newStopCmd())
 49→
 50→	return cmd
 51→}
 52→
 53→func newStopCmd() *cobra.Command {
 54→	var allFlag bool
 55→	var forceFlag bool
 56→
 57→	cmd := &cobra.Command{
 58→		Use:   "stop [session-id]",
 59→		Short: "Stop one or more active sessions",
 60→		Long: `Mark one or more active sessions as ended.
 61→
 62→Fires EventSessionStop through the state machine with a no-op action handler,
 63→so no condensation or checkpoint-writing occurs. To flush pending work, commit first.
 64→
 65→Examples:
 66→  entire sessions stop                     No sessions: exits. One session: confirm and stop. Multiple: show selector
 67→  entire sessions stop <session-id>        Stop a specific session by ID
 68→  entire sessions stop --all               Stop all active sessions
 69→  entire sessions stop --force             Skip confirmation prompt`,
 70→		Args: cobra.MaximumNArgs(1),
 71→		RunE: func(cmd *cobra.Command, args []string) error {
 72→			ctx := cmd.Context()
 73→
 74→			var sessionID string
 75→			if len(args) > 0 {
 76→				sessionID = args[0]
 77→			}
 78→
 79→			if allFlag && sessionID != "" {
 80→				return errors.New("--all and session ID argument are mutually exclusive")
 81→			}
 82→
 83→			return runStop(ctx, cmd, sessionID, allFlag, forceFlag)
 84→		},
 85→	}
 86→
 87→	cmd.Flags().BoolVar(&allFlag, "all", false, "Stop all active sessions")
 88→	cmd.Flags().BoolVarP(&forceFlag, "force", "f", false, "Skip confirmation prompt")
 89→
 90→	return cmd
 91→}
 92→
 93→// runStop is the main logic for the stop command.
 94→func runStop(ctx context.Context, cmd *cobra.Command, sessionID string, all, force bool) error {
 95→	// --session path: stop a specific session by explicit ID (no worktree scoping).
 96→	if sessionID != "" {
 97→		return runStopSession(ctx, cmd, sessionID, force)
 98→	}
 99→
100→	// List all session states
101→	states, err := strategy.ListSessionStates(ctx)
102→	if err != nil {
103→		return fmt.Errorf("failed to list sessions: %w", err)
104→	}
105→
106→	activeSessions := filterActiveSessions(states)
107→
108→	// --all path: stop all active sessions across all worktrees.
109→	if all {
110→		return runStopAll(ctx, cmd, activeSessions, force)
111→	}
112→
113→	// No-flags path: show all active sessions across all worktrees.
114→	// This aligns with `entire status` which displays sessions globally.
115→	// Users see worktree labels in the multi-select to make informed choices.
116→	if len(activeSessions) == 0 {
117→		fmt.Fprintln(cmd.OutOrStdout(), "No active sessions.")
118→		return nil
119→	}
120→
121→	// One active session: confirm + stop.
122→	if len(activeSessions) == 1 {
123→		return runStopSession(ctx, cmd, activeSessions[0].SessionID, force)
124→	}
125→
126→	// Multiple active sessions: show TUI multi-select.
127→	return runStopMultiSelect(ctx, cmd, activeSessions, force)
128→}
129→
130→// filterActiveSessions returns sessions that have not been explicitly ended.
131→// A session is considered ended if Phase == PhaseEnded OR EndedAt is set.
132→// This matches the logic in status.go's writeActiveSessions for consistency:
133→// any session visible in `entire status` should also be visible in `sessions stop`.
134→func filterActiveSessions(states []*strategy.SessionState) []*strategy.SessionState {
135→	var active []*strategy.SessionState
136→	for _, s := range states {
137→		if s == nil {
138→			continue
139→		}
140→		if s.Phase != session.PhaseEnded && s.EndedAt == nil {
141→			active = append(active, s)
142→		}
143→	}
144→	return active
145→}
146→
147→// sessionWorktreeLabel returns the worktree display label for a session.
148→// Uses WorktreeID if available, falls back to the last path component of
149→// WorktreePath, or "(unknown)" for empty values (legacy sessions without
150→// worktree tracking). Matches status.go's unknownPlaceholder convention.
151→func sessionWorktreeLabel(s *strategy.SessionState) string {
152→	if s.WorktreeID != "" {
153→		return s.WorktreeID
154→	}
155→	if s.WorktreePath != "" {
156→		return filepath.Base(s.WorktreePath)
157→	}
158→	return unknownPlaceholder
159→}
