161→// sessionPhaseLabel returns the display status for a session.
162→func sessionPhaseLabel(s *strategy.SessionState) string {
163→	if s.EndedAt != nil {
164→		return "ended"
165→	}
166→	status := string(s.Phase)
167→	if status == "" {
168→		return "idle"
169→	}
170→	return status
171→}
