349→func writeSessionInfoJSON(w io.Writer, state *strategy.SessionState, status string) error {
350→	agentLabel := string(state.AgentType)
351→	if agentLabel == "" {
352→		agentLabel = unknownPlaceholder
353→	}
354→	info := sessionInfoJSON{
355→		SessionID:      state.SessionID,
356→		Agent:          agentLabel,
357→		Model:          state.ModelName,
358→		Status:         status,
359→		WorktreeID:     state.WorktreeID,
360→		WorktreePath:   state.WorktreePath,
361→		StartedAt:      state.StartedAt,
362→		EndedAt:        state.EndedAt,
363→		LastActive:     state.LastInteractionTime,
364→		Turns:          state.SessionTurnCount,
365→		Checkpoints:    state.StepCount,
366→		LastCheckpoint: string(state.LastCheckpointID),
367→		LastPrompt:     state.LastPrompt,
368→		FilesTouched:   state.FilesTouched,
369→	}
370→	if state.TokenUsage != nil {
371→		info.Tokens = &tokenInfoJSON{
372→			Total:      totalTokens(state.TokenUsage),
373→			Input:      state.TokenUsage.InputTokens,
374→			CacheRead:  state.TokenUsage.CacheReadTokens,
375→			CacheWrite: state.TokenUsage.CacheCreationTokens,
376→			Output:     state.TokenUsage.OutputTokens,
377→		}
378→	}
379→
380→	enc := json.NewEncoder(w)
381→	enc.SetIndent("", "  ")
382→	if err := enc.Encode(info); err != nil {
383→		return fmt.Errorf("failed to encode session info: %w", err)
384→	}
385→	return nil
386→}
