464→// runStopSession stops a single session by ID, with optional confirmation.
465→func runStopSession(ctx context.Context, cmd *cobra.Command, sessionID string, force bool) error {
466→	state, err := strategy.LoadSessionState(ctx, sessionID)
467→	if err != nil {
468→		return fmt.Errorf("failed to load session: %w", err)
469→	}
470→	if state == nil {
471→		cmd.SilenceUsage = true
472→		fmt.Fprintln(cmd.ErrOrStderr(), "Session not found.")
473→		return NewSilentError(fmt.Errorf("session not found: %s", sessionID))
474→	}
475→
476→	if state.Phase == session.PhaseEnded || state.EndedAt != nil {
477→		fmt.Fprintf(cmd.OutOrStdout(), "Session %s is already stopped.\n", sessionID)
478→		return nil
479→	}
480→
481→	if !force {
482→		var confirmed bool
483→		form := NewAccessibleForm(
484→			huh.NewGroup(
485→				huh.NewConfirm().
486→					Title(fmt.Sprintf("Stop session %s?", sessionID)).
487→					Value(&confirmed),
488→			),
489→		)
490→		if err := form.Run(); err != nil {
491→			return handleFormCancellation(cmd.OutOrStdout(), "Stop", err)
492→		}
493→		if !confirmed {
494→			fmt.Fprintln(cmd.OutOrStdout(), "Stop cancelled.")
495→			return nil
496→		}
497→	}
498→
499→	return stopSessionAndPrint(ctx, cmd, state)
500→}
