 28→// GmetaRefName is the local ref for gmeta exchange format metadata.
 29→// Per gmeta spec, local metadata lives on refs/meta/local/main.
 30→const GmetaRefName = "refs/meta/local/main"
 31→
 32→// GmetaRemoteRefName is the ref name used on the remote server.
 33→// Per gmeta spec, the remote stores metadata at refs/meta/main (no local/ prefix).
 34→// Push refspec: refs/meta/local/main:refs/meta/main
 35→const GmetaRemoteRefName = "refs/meta/main"
