 37→// GmetaStore provides checkpoint storage in gmeta exchange format.
 38→// It writes metadata to refs/meta/local/main using the gmeta tree layout
 39→// convention (change-id targets with string/__value, list/__list, set/__set).
 40→//
 41→// GmetaStore is non-authoritative — it's a third write alongside v1 and v2,
 42→// proving interop with the gmeta Rust CLI.
 43→type GmetaStore struct {
 44→	repo *git.Repository
 45→	gs   *GitStore // shared entry-building helpers
 46→}
