 48→// NewGmetaStore creates a new gmeta checkpoint store backed by the given git repository.
 49→func NewGmetaStore(repo *git.Repository) *GmetaStore {
 50→	return &GmetaStore{
 51→		repo: repo,
 52→		gs:   &GitStore{repo: repo},
 53→	}
 54→}
