 56→// WriteCommitted writes or appends a session to a checkpoint in gmeta format.
 57→// If the checkpoint already exists, the new session is added alongside existing ones.
 58→// Handles both session and task checkpoints (including incremental).
 59→func (s *GmetaStore) WriteCommitted(ctx context.Context, opts WriteCommittedOptions) error {
 60→	if err := validateWriteOpts(opts); err != nil {
 61→		return err
 62→	}
 63→
 64→	refName := plumbing.ReferenceName(GmetaRefName)
 65→	if err := s.ensureRef(refName); err != nil {
 66→		return fmt.Errorf("failed to ensure gmeta ref: %w", err)
 67→	}
 68→
 69→	parentHash, rootTreeHash, err := s.getRefState(refName)
 70→	if err != nil {
 71→		return err
 72→	}
 73→
 74→	targetPath := gmetaTargetPath(opts.CheckpointID)
 75→	basePath := targetPath + "/"
 76→
 77→	// Read existing entries at this target path
 78→	entries, err := s.flattenTargetEntries(rootTreeHash, targetPath)
 79→	if err != nil {
 80→		return err
 81→	}
 82→
 83→	// Write checkpoint-level fields
 84→	s.writeCheckpointFields(opts, basePath, entries)
 85→
 86→	// Write session data
 87→	sessionID := opts.SessionID
 88→	sessionPath := basePath + "session/" + sessionID + "/"
 89→
 90→	if opts.IsTask {
 91→		if err := s.writeTaskEntries(ctx, opts, sessionPath, entries); err != nil {
 92→			return err
 93→		}
 94→	} else {
 95→		if err := s.writeSessionEntries(ctx, opts, sessionPath, entries); err != nil {
 96→			return err
 97→		}
 98→	}
 99→
100→	// Add session ID to the ordered list (if not already present)
101→	s.addSessionIDToList(basePath, sessionID, entries)
102→
103→	// Build tree and commit
104→	return s.commitEntries(refName, parentHash, rootTreeHash, targetPath, basePath, entries,
105→		fmt.Sprintf("Checkpoint: %s", opts.CheckpointID), opts.AuthorName, opts.AuthorEmail)
106→}
