108→// UpdateCommitted replaces transcript and prompts for an existing session.
109→// Used at stop time to finalize with complete session data.
110→func (s *GmetaStore) UpdateCommitted(ctx context.Context, opts UpdateCommittedOptions) error {
111→	if opts.CheckpointID.IsEmpty() {
112→		return errors.New("invalid update options: checkpoint ID is required")
113→	}
114→
115→	refName := plumbing.ReferenceName(GmetaRefName)
116→	parentHash, rootTreeHash, err := s.getRefState(refName)
117→	if err != nil {
118→		return ErrCheckpointNotFound
119→	}
120→
121→	targetPath := gmetaTargetPath(opts.CheckpointID)
122→	basePath := targetPath + "/"
123→	sessionPath := basePath + "session/" + opts.SessionID + "/"
124→
125→	entries, err := s.flattenTargetEntries(rootTreeHash, targetPath)
126→	if err != nil {
127→		return err
128→	}
129→
130→	// Check that the checkpoint exists
131→	if len(entries) == 0 {
132→		return ErrCheckpointNotFound
133→	}
134→
135→	// Replace transcript
136→	if len(opts.Transcript) > 0 {
137→		// Clear existing transcript list entries
138→		listPrefix := sessionPath + "transcript/__list/"
139→		for key := range entries {
140→			if strings.HasPrefix(key, listPrefix) {
141→				delete(entries, key)
142→			}
143→		}
144→		if err := s.writeTranscriptList(ctx, opts.Transcript, opts.Agent, sessionPath, entries); err != nil {
145→			return err
146→		}
147→	}
148→
149→	// Replace prompt
150→	if len(opts.Prompts) > 0 {
151→		promptContent := redact.String(JoinPrompts(opts.Prompts))
152→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
153→		if err != nil {
154→			return fmt.Errorf("failed to create prompt blob: %w", err)
155→		}
156→		entries[sessionPath+"prompt/__value"] = object.TreeEntry{
157→			Name: sessionPath + "prompt/__value",
158→			Mode: filemode.Regular,
159→			Hash: blobHash,
160→		}
161→	}
162→
163→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
164→	return s.commitEntries(refName, parentHash, rootTreeHash, targetPath, basePath, entries,
165→		fmt.Sprintf("Finalize checkpoint: %s", opts.CheckpointID), authorName, authorEmail)
166→}
