168→// gmetaTargetPath returns the gmeta tree base path for a checkpoint ID.
169→// Per gmeta spec: change-id/<sha1(checkpoint-id)[:2]>/<checkpoint-id>/
170→func gmetaTargetPath(cpID id.CheckpointID) string {
171→	fanout := gmetaFanout(string(cpID))
172→	return "change-id/" + fanout + "/" + string(cpID)
173→}
