175→// gmetaFanout returns the first 2 hex chars of SHA-1(value).
176→// Per gmeta spec, change-id targets use SHA-1 hash of the value for fanout.
177→func gmetaFanout(value string) string {
178→	h := sha1.Sum([]byte(value)) //nolint:gosec // gmeta spec requires SHA-1 for fanout
179→	return fmt.Sprintf("%02x", h[0])
180→}
