183→// Per gmeta spec, list entries use this format for deterministic ordering.
184→func gmetaListEntryID(content []byte, offsetMs int) string {
185→	ts := time.Now().UnixMilli() + int64(offsetMs)
186→	h := sha1.Sum(content) //nolint:gosec // gmeta spec uses SHA-1 for content hash prefix
187→	return fmt.Sprintf("%d-%05x", ts, h[:3])
