func (s *GmetaStore) ReadCommitted(_ context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
	if checkpointID.IsEmpty() {
		return nil, nil //nolint:nilnil // Empty ID means no checkpoint
	}

	refName := plumbing.ReferenceName(GmetaRefName)
	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, nil //nolint:nilnil // Ref doesn't exist
	}

	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, nil //nolint:nilnil // Invalid ref
	}

	tree, err := commit.Tree()
	if err != nil {
		return nil, nil //nolint:nilnil // Invalid tree
	}

	targetPath := gmetaTargetPath(checkpointID)
	targetTree, err := tree.Tree(targetPath)
	if err != nil {
		return nil, nil //nolint:nilnil // Checkpoint doesn't exist
	}

	summary := &CheckpointSummary{
		CheckpointID: checkpointID,
	}

